def sembrar(apps, schema_editor):
    ChronicProgram = apps.get_model("padrones", "ChronicProgram")
    ChronicProgramCie = apps.get_model("padrones", "ChronicProgramCie")
    for code, name, prefixes in PROGRAMAS:
        program, _ = ChronicProgram.objects.get_or_create(code=code, defaults={"name": name})
        for prefix in prefixes:
            ChronicProgramCie.objects.get_or_create(cie_prefix=prefix, defaults={"program": program})


def quitar(apps, schema_editor):
    ChronicProgram = apps.get_model("padrones", "ChronicProgram")
    ChronicProgramCie = apps.get_model("padrones", "ChronicProgramCie")
    codes = [code for code, _, _ in PROGRAMAS]
